import React, { useState, useMemo } from 'react';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import { useGetSaleReturnQuery } from '../posApi';
import {
  Box,
  Chip,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from '@mui/material';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import AssignmentReturnIcon from '@mui/icons-material/AssignmentReturn';
import HistoryIcon from '@mui/icons-material/History';
import { formatDate, getPriceFormatWithoutCurrency } from '../../core/utils';
import { ISaleReturnDatas } from '../../core/Interface/saleReturn.interface';
import ReturnSales from './components/ReturnSales';
import { HEADER_GRADIENT } from '../../theme/appColors';

const SalesReturnItem: React.FC = () => {
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from;

  const { saleId } = useParams<{ saleId?: string }>();

  const { data: returnData } = useGetSaleReturnQuery(saleId!, { skip: !saleId });

  const returns = useMemo(() => {
    return (returnData?.data as ISaleReturnDatas)?.returns ?? [];
  }, [returnData?.data]);

  const invoiceId = useMemo(() => {
    return (returnData?.data as ISaleReturnDatas)?.sale?.invoiceId ?? '';
  }, [returnData?.data]);

  return (
    <>
      {/* Page header */}
      <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2.5 }}>
        <Box sx={{ alignItems: 'center', display: 'flex', gap: 2 }}>
          <Box
            onClick={() => navigate(-1)}
            sx={{
              alignItems: 'center',
              background: 'rgba(255,255,255,0.15)',
              borderRadius: '8px',
              cursor: 'pointer',
              display: 'flex',
              flexShrink: 0,
              height: 36,
              justifyContent: 'center',
              transition: 'background 0.2s',
              width: 36,
              '&:hover': { background: 'rgba(255,255,255,0.25)' },
            }}
          >
            <ArrowBackIosNewIcon sx={{ color: '#fff', fontSize: 16 }} />
          </Box>
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '10px',
                display: 'flex',
                flexShrink: 0,
                height: 40,
                justifyContent: 'center',
                width: 40,
              }}
            >
              <AssignmentReturnIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: 17, fontWeight: 800, lineHeight: 1.2 }}>
                Sales Return
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 11, fontWeight: 500 }}>
                {from === 'return-list' ? 'Return History' : invoiceId || 'Process return'}
              </Typography>
            </Box>
          </Box>
        </Box>
      </Box>

      {/* Return form card */}
      <Box sx={{ mx: 2, mt: 2 }}>
        <Paper
          sx={{
            border: '1px solid #E2E8F0',
            borderRadius: '12px',
            boxShadow: 'none',
            overflow: 'hidden',
          }}
        >
          <ReturnSales passedInvoiceId={invoiceId} />
        </Paper>
      </Box>

      {/* Return history card */}
      <Box sx={{ mb: 4, mt: 3, mx: 2 }}>
        <Paper
          sx={{
            border: '1px solid #E2E8F0',
            borderRadius: '12px',
            boxShadow: 'none',
            overflow: 'hidden',
          }}
        >
          {/* Section header */}
          <Box
            sx={{
              alignItems: 'center',
              borderBottom: '1px solid #E2E8F0',
              display: 'flex',
              gap: 1.5,
              px: 3,
              py: 2,
            }}
          >
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(15,29,77,0.08)',
                borderRadius: '8px',
                color: '#0F1D4D',
                display: 'flex',
                height: 32,
                justifyContent: 'center',
                width: 32,
              }}
            >
              <HistoryIcon sx={{ fontSize: 18 }} />
            </Box>
            <Typography sx={{ color: '#0F1D4D', fontSize: '0.92rem', fontWeight: 700 }}>
              Return History
            </Typography>
            {returns.length > 0 && (
              <Chip
                label={returns.length}
                size="small"
                sx={{
                  background: '#E0E7FF',
                  borderRadius: '4px',
                  color: '#3730A3',
                  fontSize: '0.72rem',
                  fontWeight: 700,
                  height: 20,
                  ml: 0.5,
                }}
              />
            )}
          </Box>

          <Box sx={{ pb: 1, pt: 2, px: 3 }}>
            <TableContainer
              sx={{ border: '1px solid #E2E8F0', borderRadius: '8px', overflowX: 'auto', width: '100%' }}
            >
              <Table size="small" sx={{ minWidth: 550 }}>
                <TableHead>
                  <TableRow sx={{ background: '#F1F5F9' }}>
                    {['#', 'Date', 'Product Name', 'Quantity', 'Returned By', 'Return Amount'].map(
                      (h, i) => (
                        <TableCell
                          key={h}
                          align={i === 5 ? 'right' : 'left'}
                          sx={{
                            borderBottom: '2px solid #E2E8F0',
                            color: '#374151',
                            fontSize: '0.75rem',
                            fontWeight: 700,
                            letterSpacing: '0.03em',
                            py: 1.25,
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {h}
                        </TableCell>
                      )
                    )}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {returns.length === 0 ? (
                    <TableRow>
                      <TableCell
                        align="center"
                        colSpan={6}
                        sx={{ color: '#94A3B8', fontSize: '0.88rem', py: 4 }}
                      >
                        No return history found
                      </TableCell>
                    </TableRow>
                  ) : (
                    returns
                      .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                      .flatMap((row, index) =>
                        row.items.map((item, itemIndex) => (
                          <TableRow
                            key={`${row.saleId}-${item.id}`}
                            sx={{
                              background:
                                (page * rowsPerPage + index) % 2 === 0 ? '#fff' : '#F8FAFC',
                              '&:last-child td': { borderBottom: 'none' },
                            }}
                          >
                            <TableCell sx={{ color: '#94A3B8', fontSize: '0.84rem', py: 1.25 }}>
                              {itemIndex === 0 ? (
                                <Chip
                                  label={page * rowsPerPage + index + 1}
                                  size="small"
                                  sx={{
                                    background: '#F1F5F9',
                                    borderRadius: '4px',
                                    color: '#475569',
                                    fontSize: '0.72rem',
                                    fontWeight: 600,
                                    height: 20,
                                  }}
                                />
                              ) : (
                                ''
                              )}
                            </TableCell>
                            <TableCell sx={{ color: '#475569', fontSize: '0.84rem', py: 1.25 }}>
                              {itemIndex === 0 ? formatDate(new Date(row.dateTime)) : ''}
                            </TableCell>
                            <TableCell
                              sx={{
                                color: '#1E293B',
                                fontSize: '0.84rem',
                                fontWeight: 500,
                                py: 1.25,
                              }}
                            >
                              {item.productName}
                            </TableCell>
                            <TableCell sx={{ py: 1.25 }}>
                              <Chip
                                label={item.qty}
                                size="small"
                                sx={{
                                  background: '#E0E7FF',
                                  borderRadius: '4px',
                                  color: '#3730A3',
                                  fontSize: '0.75rem',
                                  fontWeight: 700,
                                  height: 20,
                                }}
                              />
                            </TableCell>
                            <TableCell sx={{ color: '#475569', fontSize: '0.84rem', py: 1.25 }}>
                              {item.returnedBy}
                            </TableCell>
                            <TableCell
                              align="right"
                              sx={{
                                color: '#DC2626',
                                fontSize: '0.88rem',
                                fontWeight: 700,
                                py: 1.25,
                              }}
                            >
                              {getPriceFormatWithoutCurrency(item.amount)}
                            </TableCell>
                          </TableRow>
                        ))
                      )
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box sx={{ px: 2 }}>
            <TablePagination
              component="div"
              count={returns.length}
              onPageChange={(_, newPage) => setPage(newPage)}
              onRowsPerPageChange={(e) => {
                setRowsPerPage(+e.target.value);
                setPage(0);
              }}
              page={page}
              rowsPerPage={rowsPerPage}
            />
          </Box>
        </Paper>
      </Box>
    </>
  );
};

export default SalesReturnItem;
