import React, { useMemo, useState } from 'react';
import {
  useGetUserQuery,
  useNewSalesReturnMutation,
  useGetSaleReturnQuery,
} from '../../posApi';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  Divider,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import BadgeIcon from '@mui/icons-material/Badge';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import PersonIcon from '@mui/icons-material/Person';
import PhoneIcon from '@mui/icons-material/Phone';
import { useTranslation } from 'react-i18next';
import { IUserInfo } from '../../../core/Interface/user.interface';
import TopInfoSkeleton from '../../Dashboard/TopInfoSkeleton';
import { formatDateTime, getPriceFormat } from '../../../core/utils';
import { useNotifier } from '../../../core/Notifier';
import { useParams } from 'react-router-dom';
import { ISaleReturnDatas } from '../../../core/Interface/saleReturn.interface';

const InfoRow = ({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) => (
  <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, minWidth: 0 }}>
    <Box
      sx={{
        alignItems: 'center',
        background: 'rgba(15,29,77,0.08)',
        borderRadius: '8px',
        color: '#0F1D4D',
        display: 'flex',
        flexShrink: 0,
        height: 32,
        justifyContent: 'center',
        width: 32,
      }}
    >
      {icon}
    </Box>
    <Box sx={{ minWidth: 0 }}>
      <Typography
        sx={{
          color: '#94A3B8',
          fontSize: '0.72rem',
          fontWeight: 600,
          letterSpacing: '0.04em',
          textTransform: 'uppercase',
        }}
      >
        {label}
      </Typography>
      <Typography
        noWrap
        sx={{ color: '#1E293B', fontSize: '0.88rem', fontWeight: 600 }}
      >
        {value || '—'}
      </Typography>
    </Box>
  </Box>
);

const ReturnSales = ({ passedInvoiceId: _passedInvoiceId }: { passedInvoiceId: string }) => {
  const { saleId } = useParams<{ saleId?: string }>();
  const {
    data: returnData,
    isError,
    isLoading,
  } = useGetSaleReturnQuery(saleId!, { skip: !saleId });

  const returnUseMemo = useMemo(() => {
    return (returnData?.data ?? {}) as ISaleReturnDatas;
  }, [returnData]);

  const { t } = useTranslation(['common', 'return']);
  const { showErrorMessage, showMessage } = useNotifier();

  const [newSalesReturn, { isLoading: isSubmitting }] = useNewSalesReturnMutation();
  const [returnQuantities, setReturnQuantities] = useState<{ [productId: string]: number }>({});
  const [, setErrors] = useState<{ [productId: string]: string }>({});

  const handleReturnQtyChange = (productId: string, value: number, maxQty: number) => {
    const newQty = Math.max(0, value);
    const errorMsg = newQty > maxQty ? `Max available: ${maxQty}` : '';
    setReturnQuantities((prev) => ({ ...prev, [productId]: newQty }));
    setErrors((prev) => ({ ...prev, [productId]: errorMsg }));
  };

  const { data: companyData } = useGetUserQuery();
  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const handleSubmit = async () => {
    try {
      const isValid = returnUseMemo.saleItems?.every((item) => {
        const returnQty = returnQuantities[item.productId] || 0;
        return returnQty <= item.availableToReturnQty;
      });

      if (!isValid) {
        showErrorMessage('Return quantity cannot be more than available quantity');
        return;
      }

      const temData = {
        dateTime: returnUseMemo?.sale.dateTime,
        saleId,
        items: returnUseMemo?.saleItems?.map((item) => ({
          productId: item.productId,
          returnQty: returnQuantities[item.productId] || 0,
        })),
      };

      const returnResponse = await newSalesReturn(temData).unwrap();
      if (!returnResponse.status) {
        showErrorMessage(returnResponse.message);
      } else {
        showMessage(returnResponse.message);
        setReturnQuantities({});
        setErrors({});
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const totalReturnAmount = useMemo(() => {
    if (!returnUseMemo?.saleItems) return 0;
    return returnUseMemo.saleItems.reduce((acc, item) => {
      const returnQty = returnQuantities[item.productId] || 0;
      return acc + returnQty * item.sellingPrice;
    }, 0);
  }, [returnQuantities, returnUseMemo]);

  const totalReturnedAmount = useMemo(() => {
    if (!returnUseMemo?.returns || !Array.isArray(returnUseMemo.returns)) return 0;
    return returnUseMemo.returns.reduce((acc, item) => acc + (item.returnAmount || 0), 0);
  }, [returnUseMemo]);

  return (
    <Box data-testid="salesReturn">
      {isLoading &&
        [1, 2, 3, 4].map((i) => (
          <Grid item key={i} xs={4}>
            <TopInfoSkeleton data-testid="top--skeleton" />
          </Grid>
        ))}
      {!isLoading && isError && (
        <Typography align="center" data-testid="top-nodata" width="100%">
          {t('common:noData')}
        </Typography>
      )}
      {!isLoading && !isError && returnUseMemo?.sale && (
        <>
          {/* Info strip */}
          <Box sx={{ background: '#F8FAFC', borderBottom: '1px solid #E2E8F0', px: 3, py: 2 }}>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6} md={3}>
                <InfoRow
                  icon={<BadgeIcon sx={{ fontSize: 16 }} />}
                  label={t('return:invoiceId')}
                  value={returnUseMemo.sale.invoiceId}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <InfoRow
                  icon={<PhoneIcon sx={{ fontSize: 16 }} />}
                  label="Mobile"
                  value={returnUseMemo.sale.mobile}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <InfoRow
                  icon={<PersonIcon sx={{ fontSize: 16 }} />}
                  label="Sale By"
                  value={returnUseMemo.sale.saleBy}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <InfoRow
                  icon={<CalendarTodayIcon sx={{ fontSize: 16 }} />}
                  label="Date"
                  value={formatDateTime(new Date(returnUseMemo.sale.dateTime))}
                />
              </Grid>
            </Grid>
          </Box>

          {/* Financial summary */}
          <Box
            sx={{
              borderBottom: '1px solid #E2E8F0',
              display: 'flex',
              gap: 4,
              justifyContent: 'flex-end',
              px: 3,
              py: 1.5,
            }}
          >
            <Box sx={{ textAlign: 'right' }}>
              <Typography
                sx={{
                  color: '#94A3B8',
                  fontSize: '0.72rem',
                  fontWeight: 600,
                  letterSpacing: '0.04em',
                  textTransform: 'uppercase',
                }}
              >
                Total Amount
              </Typography>
              <Typography sx={{ color: '#0F1D4D', fontSize: '1rem', fontWeight: 700 }}>
                {getPriceFormat(returnUseMemo.sale.total, currencyCode)}
              </Typography>
            </Box>
            <Box sx={{ textAlign: 'right' }}>
              <Typography
                sx={{
                  color: '#94A3B8',
                  fontSize: '0.72rem',
                  fontWeight: 600,
                  letterSpacing: '0.04em',
                  textTransform: 'uppercase',
                }}
              >
                Total Returned
              </Typography>
              <Typography
                sx={{
                  color: totalReturnedAmount > 0 ? '#DC2626' : '#94A3B8',
                  fontSize: '1rem',
                  fontWeight: 700,
                }}
              >
                {getPriceFormat(totalReturnedAmount, currencyCode)}
              </Typography>
            </Box>
          </Box>

          {/* Items table */}
          <Box sx={{ pb: 1, pt: 2.5, px: 3 }}>
            <Typography
              sx={{
                color: '#0F1D4D',
                fontSize: '0.78rem',
                fontWeight: 700,
                letterSpacing: '0.06em',
                mb: 1,
                textTransform: 'uppercase',
              }}
            >
              Items
            </Typography>
            <TableContainer
              sx={{ border: '1px solid #E2E8F0', borderRadius: '8px', overflow: 'hidden' }}
            >
              <Table size="small">
                <TableHead>
                  <TableRow sx={{ background: '#F1F5F9' }}>
                    {[
                      { label: t('return:qty'), align: 'left' as const },
                      { label: t('return:returnQty'), align: 'left' as const },
                      { label: t('return:description'), align: 'left' as const },
                      { label: t('return:sellingPrice'), align: 'right' as const },
                      { label: t('return:amount'), align: 'right' as const },
                    ].map(({ label, align }) => (
                      <TableCell
                        key={label}
                        align={align}
                        sx={{
                          borderBottom: '2px solid #E2E8F0',
                          color: '#374151',
                          fontSize: '0.75rem',
                          fontWeight: 700,
                          letterSpacing: '0.03em',
                          py: 1.25,
                          whiteSpace: 'nowrap',
                        }}
                      >
                        {label}
                      </TableCell>
                    ))}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {returnUseMemo.saleItems?.map((item, index) => (
                    <TableRow
                      key={index}
                      sx={{
                        background: index % 2 === 0 ? '#fff' : '#F8FAFC',
                        '&:last-child td': { borderBottom: 'none' },
                      }}
                    >
                      <TableCell align="left" sx={{ color: '#334155', fontSize: '0.84rem', py: 1.25 }}>
                        <Chip
                          label={item.qty}
                          size="small"
                          sx={{
                            background: '#E0E7FF',
                            borderRadius: '4px',
                            color: '#3730A3',
                            fontSize: '0.75rem',
                            fontWeight: 700,
                            height: 20,
                          }}
                        />
                      </TableCell>
                      <TableCell align="left" sx={{ py: 1.25 }}>
                        <Box alignItems="center" display="flex" gap={1}>
                          <TextField
                            autoComplete="off"
                            inputProps={{ style: { fontSize: '0.84rem', padding: '4px 8px' } }}
                            onChange={(e) =>
                              handleReturnQtyChange(
                                item.productId,
                                parseFloat(e.target.value || '0'),
                                item.availableToReturnQty
                              )
                            }
                            size="small"
                            sx={{
                              width: '80px',
                              '& .MuiOutlinedInput-root': {
                                borderRadius: '6px',
                                '& fieldset': { borderColor: '#CBD5E1' },
                                '&:hover fieldset': { borderColor: '#0F8B8D' },
                                '&.Mui-focused fieldset': { borderColor: '#0F8B8D' },
                              },
                            }}
                            type="number"
                            value={
                              returnQuantities[item.productId] !== undefined
                                ? returnQuantities[item.productId]
                                : 0
                            }
                          />
                          <Chip
                            label={`/${item.availableToReturnQty}`}
                            size="small"
                            sx={{
                              background: '#DCFCE7',
                              borderRadius: '4px',
                              color: '#16A34A',
                              fontSize: '0.72rem',
                              fontWeight: 600,
                              height: 18,
                            }}
                          />
                        </Box>
                      </TableCell>
                      <TableCell
                        sx={{
                          color: '#1E293B',
                          fontSize: '0.84rem',
                          fontWeight: 500,
                          maxWidth: 180,
                          py: 1.25,
                          wordBreak: 'break-word',
                        }}
                      >
                        {item.productName}
                      </TableCell>
                      <TableCell align="right" sx={{ color: '#475569', fontSize: '0.84rem', py: 1.25 }}>
                        {getPriceFormat(item.sellingPrice, currencyCode)}
                      </TableCell>
                      <TableCell
                        align="right"
                        sx={{
                          color: (returnQuantities[item.productId] || 0) > 0 ? '#0F1D4D' : '#94A3B8',
                          fontSize: '0.88rem',
                          fontWeight: 700,
                          py: 1.25,
                        }}
                      >
                        {getPriceFormat(
                          (returnQuantities[item.productId] || 0) * item.sellingPrice,
                          currencyCode
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          {/* Footer: total + submit */}
          <Divider sx={{ mx: 3 }} />
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              gap: 4,
              justifyContent: 'flex-end',
              px: 3,
              py: 2,
            }}
          >
            <Box sx={{ textAlign: 'right' }}>
              <Typography
                sx={{
                  color: '#94A3B8',
                  fontSize: '0.72rem',
                  fontWeight: 600,
                  letterSpacing: '0.04em',
                  textTransform: 'uppercase',
                }}
              >
                {t('return:total')}
              </Typography>
              <Typography sx={{ color: '#0F8B8D', fontSize: '1.15rem', fontWeight: 800 }}>
                {getPriceFormat(totalReturnAmount, currencyCode)}
              </Typography>
            </Box>
            <Button
              disabled={isSubmitting}
              onClick={handleSubmit}
              sx={{ borderRadius: '8px', fontWeight: 700, height: 42, minWidth: 160, px: 3 }}
              type="submit"
              variant="contained"
            >
              {isSubmitting && (
                <CircularProgress size={16} sx={{ color: 'white', mr: 1 }} />
              )}
              {t('common:submit')}
            </Button>
          </Box>
        </>
      )}
    </Box>
  );
};

export default React.memo(ReturnSales);
